    def sign(self, path: str, api: list[str] = ['public'], method: str = 'GET', params: dict = {}) -> dict:
        apiName = api[0]
        baseApiUrl = self.safe_string(self.urls['api'], apiName)
        if baseApiUrl is None:
            raise ExchangeError(self.id + ' sign() has no API URL for ' + apiName)
        implodePath = self.implode_params(path, params)
        queryParams = self.omit(params, self.extract_params(path))
        url = baseApiUrl + '/' + implodePath
        if (method.upper() != 'POST') and (len(queryParams) > 0):
            url += '?' + self.urlencode(queryParams)
        return {
            'url': url,
            'method': method,
            'body': None,
            'headers': {'Accept': 'application/json'},
        }

    def fetch_markets(self, params: dict = {}) -> list[Market]:
        """ fetchMarkets
        retrieves the list of markets from the public products endpoint

        https://trade.smartcore.su/api/products

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict[]: a list of unified market structures
        """
        products = self.publicGetProducts(params)
        result = []
        for i in range(0, len(products)):
            product = products[i]
            result.append(self.parse_market(product))
        return result

